const raw = String($json.output || '').trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');
const obj = JSON.parse(raw);
for (const k of ['respuesta','user_name','status','last_summary']) if (typeof obj[k] !== 'string' || !obj[k].trim()) throw new Error('Contrato de memoria inválido: '+k);
if (!obj.datos_clave || Array.isArray(obj.datos_clave) || typeof obj.datos_clave !== 'object') throw new Error('Datos clave inválidos');
const entrada=$('Entrada especialista').first().json;
return [{json:{status:'success',worker:'REGISTRO',request_id:entrada.request_id,output:obj.respuesta,error_code:'',error_message:'',memory_user_name:obj.user_name.slice(0,120),memory_status:obj.status.slice(0,120),memory_summary:obj.last_summary.slice(0,1800),memory_facts:obj.datos_clave}}];
